insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  15,
  $wyb$A content pipeline that takes a weekly input (your wins, ideas, links) and a custom voice persona you write once, and asks the AI to generate five distinct LinkedIn post types -- insight, story, how-to, opinion, results -- in a Streamlit review UI where you edit before copying into Buffer, Postiz, or LinkedIn directly. A cliche guard flags any post that slips in a corporate buzzword the persona explicitly banned, instead of trusting the prompt's rules alone.$wyb$,
  $wyl$[
  "Write a persona file that controls tone, voice, and hard rules -- and reuse the exact same banned-phrase list in both the prompt and a code-level guard",
  "Design a 5-section synthesis prompt using bracket markers instead of JSON",
  "Parse a reply that might be missing some sections, without losing the ones the AI got right",
  "Build a Streamlit review UI so nothing gets scheduled without a human reading it first",
  "Save approved content to files ready for a scheduler, instead of trying to auto-post"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.6 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "110 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A few real notes about your week (a win, an idea, a link) to test with"
  ],
  "outcomes": [
    "Write a persona file that controls tone, voice, and hard rules for everything generated",
    "Generate 5 distinct LinkedIn post types from one week of raw notes in a single AI call",
    "Catch a banned cliche in code, using the same list the prompt already gave the AI",
    "Review and edit every post in a Streamlit UI before anything is considered 'approved'",
    "Save approved posts as ready-to-paste files instead of trying to auto-schedule them"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Set up sdt_ai.py and write your persona",
      "time": "30 min",
      "description": "The persona file is the entire difference between generic AI-sounding posts and ones that sound like you. Get the AI gateway wired up, then spend real time on this file before generating a single post - it's the one input you'll never get from a prompt alone.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# Overridable via .env if you ever want to try a different model.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-2.5-flash\")\nGEMINI_URL = (\n    f\"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent\"\n)\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                GEMINI_URL, params={\"key\": api_key}, json=payload, timeout=90\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            last_problem = \"Gemini is busy (503 - high demand on the free tier)\"\n            time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `persona.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the LinkedIn Content Creator Agent.\n\nThis file is the entire difference between generic AI-sounding LinkedIn\nposts and ones that sound like you. Short, concrete rules and a couple\nof real example posts teach the AI your voice far better than a pile of\nadjectives like \"professional but approachable\" ever could.\n\"\"\"\n\nPERSONA_RULES = \"\"\"\nVoice: direct, a little informal, no corporate buzzwords.\nLength: 80-150 words per post, short paragraphs (1-3 sentences each).\nNever use these phrases: \"game-changer\", \"circle back\", \"synergy\",\n\"thought leader\", \"level up\", \"unpack\", \"double-click on\".\nAlways end with either a genuine question to the audience, or a\none-line takeaway - never a generic \"Thoughts?\" with nothing else.\n\"\"\"\n\nEXAMPLE_POSTS = \"\"\"\nExample 1 (insight post):\nMost teams ship a feature, then wonder why nobody uses it.\nThe teams that don't have this problem talked to 5 users BEFORE writing\na line of code. Not a survey. An actual 15-minute call.\nIt's not glamorous. It works.\n\nExample 2 (story post):\nThree years ago I got rejected from my dream job.\nThe feedback was brutal but specific: \"You can code, but you can't\nexplain why the code matters.\"\nI spent the next year fixing exactly that. Got a better job at a\nbetter company 14 months later.\nSpecific feedback, even when it stings, is a gift.\n\"\"\"\n\n\ndef full_persona_text():\n    \"\"\"Returns the persona rules plus example posts, ready to drop into a prompt.\"\"\"\n    return PERSONA_RULES + \"\\n\" + EXAMPLE_POSTS\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check it loads correctly:  python persona.py\n    text = full_persona_text()\n    assert \"game-changer\" in text  # it's in the BANNED list, correctly present as a rule\n    assert \"Example 1\" in text\n    print(\"Persona loaded:\", len(text), \"characters\")\n    print(\"\\nEdit PERSONA_RULES and EXAMPLE_POSTS above to sound like YOU, not this sample voice.\")\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python persona.py`. You should see the character count printed, a reminder to edit PERSONA_RULES and EXAMPLE_POSTS to match your own voice, ending with `All checks passed.`"
        },
        {
          "instruction": "Now edit PERSONA_RULES and replace both EXAMPLE_POSTS with two real posts you've actually written (or would write) - not the samples.",
          "verify": "Re-run `python persona.py` and confirm it still loads without error after your edits. The samples exist to show the shape - your real voice comes from replacing them."
        }
      ],
      "goFurther": "Add a THIRD example post in a completely different post type (e.g. a results post) - more real examples generally teach the voice better than more written rules."
    },
    {
      "number": 2,
      "title": "Generate 5 post types with a cliche guard",
      "time": "35 min",
      "description": "This is the heart of the project - turning a week of raw notes into 5 distinct posts. It's also where the project makes its style promise real: the exact banned-phrase list the prompt gives the AI is checked again in code, since a prompt rule is a request, not a guarantee.",
      "steps": [
        {
          "instruction": "Create `generator.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the LinkedIn Content Creator Agent.\n\nTurns one week of raw input (wins, ideas, links) into 5 distinct post\ntypes, using your persona from persona.py. Also carries this project's\nsafety guard: every generated post is checked against the SAME banned\nphrase list the prompt already asked the AI to avoid, since a prompt\nrule is a request, not a guarantee.\n\"\"\"\n\nfrom persona import full_persona_text\nfrom sdt_ai import ask_ai\n\nPOST_TYPES = [\"INSIGHT\", \"STORY\", \"HOWTO\", \"OPINION\", \"RESULTS\"]\n\n# The exact phrases persona.py's PERSONA_RULES already asks the AI to\n# avoid. Defined once here (not copy-pasted into the guard separately)\n# so the prompt and the guard can never quietly drift out of sync.\nBANNED_PHRASES = [\n    \"game-changer\", \"circle back\", \"synergy\", \"thought leader\",\n    \"level up\", \"unpack\", \"double-click on\",\n]\n\n# Stop sending raw notes to the AI after this many characters. A MONEY\n# decision: a week's worth of notes rarely needs to be huge to generate\n# 5 posts, and every extra character here is extra input-token cost on\n# a prompt that already includes the persona and example posts too.\nMAX_INPUT_CHARACTERS = 2000\n\n\ndef build_prompt(weekly_input):\n    trimmed = weekly_input.strip()[:MAX_INPUT_CHARACTERS]\n    return f\"\"\"{full_persona_text()}\n\nUsing the raw notes below (this week's wins, ideas, and links), write 5\nDIFFERENT LinkedIn posts, one of each type:\n\n[INSIGHT]\na post sharing a non-obvious lesson or observation\n\n[STORY]\na short personal story with a clear takeaway\n\n[HOWTO]\na practical, numbered or bulleted how-to post\n\n[OPINION]\na post taking a clear, slightly contrarian stance\n\n[RESULTS]\na post sharing a specific result or number, with context on how it was achieved\n\n[END]\n\nDo not add any explanation outside these 5 sections. Do not invent\nresults, numbers, or events that are not implied by the notes below.\n\nTHIS WEEK'S NOTES:\n{trimmed}\"\"\"\n\n\ndef contains_cliche(text):\n    \"\"\"\n    Returns True if a generated post uses one of the exact phrases the\n    prompt already told the AI to avoid.\n\n        contains_cliche(\"This is a total game-changer for our team.\") -> True\n\n    Case-insensitive substring check - simple and a little over-eager\n    beats a fragile attempt at deep language understanding.\n    \"\"\"\n    lowered = text.lower()\n    return any(phrase in lowered for phrase in BANNED_PHRASES)\n\n\ndef parse_posts(reply):\n    \"\"\"\n    Turns the AI's marker-formatted reply into a dict of posts, with\n    each one checked for cliches.\n\n        {\"INSIGHT\": \"...\", \"STORY\": \"...\", ...}\n\n    Same forgiving [MARKER] approach used throughout this course:\n    anything that isn't a recognised marker is dropped rather than\n    raising, so a slightly-off reply still returns the post types it DID\n    get right.\n\n    A post containing a banned cliche is kept, but visibly flagged\n    rather than silently dropped or silently shipped - you decide what\n    to do with it, the tool doesn't decide for you.\n    \"\"\"\n    sections = {name: [] for name in POST_TYPES}\n    current = None\n\n    for raw_line in reply.splitlines():\n        line = raw_line.strip()\n        marker = line.strip(\"[]\").upper()\n        is_marker = line.startswith(\"[\") and line.endswith(\"]\")\n\n        if is_marker and marker == \"END\":\n            break\n        if is_marker and marker in sections:\n            current = marker\n            continue\n        if current is None:\n            continue\n        if line.startswith(\"```\"):\n            continue\n        if line:\n            sections[current].append(line)\n\n    posts = {}\n    for name, lines in sections.items():\n        if not lines:\n            continue\n        text = \"\\n\".join(lines).strip()\n        if contains_cliche(text):\n            text = \"[CONTAINS CLICHE - REVIEW BEFORE POSTING]\\n\\n\" + text\n        posts[name] = text\n\n    return posts\n\n\ndef generate_posts(weekly_input):\n    \"\"\"\n    The main function. Give it this week's raw notes, get back a dict of\n    up to 5 posts.\n\n        posts = generate_posts(\"Shipped the new onboarding flow, signups up 18%\")\n    \"\"\"\n    prompt = build_prompt(weekly_input)\n    reply = ask_ai(prompt, max_tokens=1200, project=\"linkedin-content-creator\")\n    posts = parse_posts(reply)\n\n    if not posts:\n        raise ValueError(\n            \"The AI replied, but not in the format we asked for.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    return posts\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing and the cliche guard\n    # work - no AI call, no credits spent:  python generator.py\n\n    print(\"Checking a well-formed, clean reply...\")\n    good_reply = \"\"\"[INSIGHT]\nMost teams ship a feature, then wonder why nobody uses it.\n\n[STORY]\nThree years ago I got rejected from my dream job over vague feedback.\n\n[HOWTO]\n1. Talk to 5 users before writing code.\n2. Ship the smallest version that answers their question.\n\n[OPINION]\nRoadmaps planned a year out are usually fiction.\n\n[RESULTS]\nWe cut onboarding time from 12 minutes to 4 by removing two screens.\n\n[END]\"\"\"\n    posts = parse_posts(good_reply)\n    assert set(posts.keys()) == set(POST_TYPES)\n    assert \"CONTAINS CLICHE\" not in posts[\"INSIGHT\"]\n    print(\"  OK - all 5 post types parsed, none flagged\")\n\n    print(\"\\nChecking a reply where one post slips in a banned cliche...\")\n    cliche_reply = \"\"\"[INSIGHT]\nThis new workflow is a total game-changer for how we ship.\n\n[STORY]\nA clean story with no buzzwords at all.\n\n[HOWTO]\nSteps without any buzzwords.\n\n[OPINION]\nA clear opinion.\n\n[RESULTS]\nA specific result.\n\n[END]\"\"\"\n    posts = parse_posts(cliche_reply)\n    assert \"[CONTAINS CLICHE - REVIEW BEFORE POSTING]\" in posts[\"INSIGHT\"]\n    assert \"[CONTAINS CLICHE\" not in posts[\"STORY\"]\n    print(\"  OK - only the post with the cliche got flagged, the others were left clean\")\n\n    print(\"\\nChecking a reply missing some post types entirely...\")\n    partial_reply = \"\"\"[INSIGHT]\nJust one post this time.\n\n[END]\"\"\"\n    posts = parse_posts(partial_reply)\n    assert list(posts.keys()) == [\"INSIGHT\"]\n    print(\"  OK - returned just the one section instead of crashing over the missing four\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python generator.py` (no AI call, no credits spent - this only tests parsing and the cliche guard against fake replies). You should see all 5 post types parsed cleanly from a well-formed reply, then a reply where only the post using \"game-changer\" gets flagged `[CONTAINS CLICHE - REVIEW BEFORE POSTING]` while the others stay clean, then a reply missing 4 of 5 sections correctly returning just the one it got - ending with `All checks passed.`"
        },
        {
          "instruction": "Now generate a real week's posts from your own notes:",
          "prompt": "python -c \"from generator import generate_posts; posts = generate_posts('Shipped the new onboarding flow this week, signups up 18 percent'); [print(f'--- {k} ---\\n{v}\\n') for k, v in posts.items()]\"",
          "verify": "You should see 5 distinct posts printed, each recognisably a different type, none inventing a specific number your notes didn't mention."
        }
      ],
      "goFurther": "🛠️ Add a 6th BANNED_PHRASES entry that's specific to YOUR industry's jargon, and confirm a post using it gets correctly flagged the same way \"game-changer\" does."
    },
    {
      "number": 3,
      "title": "Build the Streamlit review UI",
      "time": "30 min",
      "description": "Nothing in this project auto-posts or auto-schedules. This build gives you a place to read, edit, and approve each post before it ever leaves your machine - a bad post going out under your name costs a lot more than the two minutes this UI takes.",
      "steps": [
        {
          "instruction": "Create `app.py` with this code, then run it:",
          "prompt": "\"\"\"\nStep 3 of the LinkedIn Content Creator Agent.\n\nA Streamlit app to review, edit, and approve the week's 5 generated\nposts before you copy them into Buffer, Postiz, or LinkedIn directly.\nThis project doesn't auto-post or auto-schedule anything - a bad post\ngoing out under your name is worse than spending 2 extra minutes\ncopy-pasting.\n\"\"\"\n\nimport streamlit as st\n\nfrom generator import generate_posts\nfrom sdt_ai import AIError\n\nst.set_page_config(page_title=\"LinkedIn Content Creator\", page_icon=\"\\U0001F4DD\")\nst.title(\"LinkedIn Content Creator\")\n\nweekly_input = st.text_area(\n    \"This week's wins, ideas, and links\",\n    height=150,\n    placeholder=\"e.g. Shipped the new onboarding flow, signups up 18%. Read a great post about...\",\n)\n\nif st.button(\"Generate 5 posts\", type=\"primary\"):\n    if not weekly_input.strip():\n        st.warning(\"Add a few notes first - even a couple of bullet points works.\")\n    else:\n        with st.spinner(\"Writing 5 posts in your voice...\"):\n            try:\n                st.session_state[\"posts\"] = generate_posts(weekly_input)\n            except AIError as problem:\n                st.error(f\"AI request failed: {problem}\")\n            except ValueError as problem:\n                st.error(str(problem))\n\nif \"posts\" in st.session_state:\n    for post_type, text in st.session_state[\"posts\"].items():\n        with st.expander(post_type.title(), expanded=True):\n            st.text_area(\n                f\"Edit your {post_type.lower()} post\",\n                value=text,\n                height=180,\n                key=f\"edit_{post_type}\",\n                label_visibility=\"collapsed\",\n            )\n\n\nif __name__ == \"__main__\":\n    print(\"This is a Streamlit app - run it with: streamlit run app.py\")\n    print(\"There's no offline self-test here - generator.py already covers\")\n    print(\"the parsing and cliche-guard logic this app depends on.\")\n",
          "verify": "Run `streamlit run app.py`. Paste in a few notes and click \"Generate 5 posts\" - you should see 5 expandable sections, each with an editable text box pre-filled with that post type's draft. Edit one and confirm your edit stays in the box (Streamlit's session state keeps it, rather than resetting on the next interaction)."
        }
      ],
      "goFurther": "Add a character counter warning when an edited post goes over LinkedIn's ~3000 character limit, using st.caption() next to each text area."
    },
    {
      "number": 4,
      "title": "Save approved posts for scheduling",
      "time": "15 min",
      "description": "The last step: once you're happy with the edited posts, save each one as its own file, ready to paste into Buffer, Postiz, or LinkedIn directly.",
      "steps": [
        {
          "instruction": "Create `save_posts.py` with this code:",
          "prompt": "\"\"\"\nStep 4 of the LinkedIn Content Creator Agent - saves the approved posts\nfrom this week as separate text files, ready to copy into Buffer,\nPostiz, or LinkedIn directly.\n\"\"\"\n\nimport os\nimport re\nfrom datetime import datetime\n\n\ndef _slugify(text):\n    slug = re.sub(r\"[^a-z0-9]+\", \"-\", text.lower()).strip(\"-\")\n    return slug[:30] or \"post\"\n\n\ndef save_posts(posts, output_dir=\"posts_output\"):\n    \"\"\"\n    Saves each post as its own .txt file, named by post type and date.\n\n        paths = save_posts({\"INSIGHT\": \"...\", \"STORY\": \"...\"})\n\n    One file per post type, not one combined file - you'll copy these\n    into a scheduler one at a time, on different days of the week, so a\n    combined file just means extra copy-paste work every time.\n\n    Returns the list of paths written.\n    \"\"\"\n    os.makedirs(output_dir, exist_ok=True)\n    date_str = datetime.now().strftime(\"%Y%m%d\")\n    paths = []\n\n    for post_type, text in posts.items():\n        path = os.path.join(output_dir, f\"{date_str}_{_slugify(post_type)}.txt\")\n        with open(path, \"w\", encoding=\"utf-8\") as f:\n            f.write(text)\n        paths.append(path)\n\n    return paths\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check saving works:  python save_posts.py\n    sample = {\n        \"INSIGHT\": \"Most teams ship a feature, then wonder why nobody uses it.\",\n        \"STORY\": \"Three years ago I got rejected from my dream job.\",\n    }\n    paths = save_posts(sample, output_dir=\"posts_output_test\")\n    assert len(paths) == 2\n    for path in paths:\n        assert os.path.exists(path)\n    print(\"Saved\", len(paths), \"files:\")\n    for path in paths:\n        print(\" \", path)\n\n    with open(paths[0], encoding=\"utf-8\") as f:\n        saved_content = f.read()\n    assert saved_content == sample[\"INSIGHT\"]\n    print(\"\\nConfirmed: saved file content matches exactly what was passed in.\")\n",
          "verify": "Run `python save_posts.py`. You should see 2 files saved and their paths printed, ending with `Confirmed: saved file content matches exactly what was passed in.` Open one of the saved .txt files in posts_output_test/ and confirm it matches."
        },
        {
          "instruction": "Add a \"Save approved posts\" button to app.py that calls save_posts() with the CURRENT (possibly edited) text from each expander - not the original AI output - then shows the saved file paths.",
